import { test, expect } from '@playwright/test';

test.describe('Breadcrumbs Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/products/electronics/phones');
  });

  test('should display breadcrumbs showing current location in site hierarchy', async ({ page }) => {
    // Verify breadcrumbs container is visible
    const breadcrumbs = page.getByRole('navigation', { name: /breadcrumbs/i });
    await expect(breadcrumbs).toBeVisible();

    // Verify breadcrumb links exist and contain correct text
    const homeLink = page.getByRole('link', { name: /home/i });
    await expect(homeLink).toBeVisible();
    await expect(homeLink).toHaveAttribute('href', '/');

    const productsLink = page.getByRole('link', { name: /products/i });
    await expect(productsLink).toBeVisible();
    await expect(productsLink).toHaveAttribute('href', '/products');

    const electronicsLink = page.getByRole('link', { name: /electronics/i });
    await expect(electronicsLink).toBeVisible();
    await expect(electronicsLink).toHaveAttribute('href', '/products/electronics');

    const phonesCurrentPage = page.getByText(/phones/i);
    await expect(phonesCurrentPage).toBeVisible();
    await expect(phonesCurrentPage).not.toHaveAttribute('href');

    // Verify breadcrumb structure using getByRole
    const breadcrumbItems = page.getByRole('link').filter({ hasText: /home|products|electronics|phones/i });
    const itemCount = await breadcrumbItems.count();
    expect(itemCount).toBe(4);
  });

  test('should handle breadcrumbs when navigating to a root page', async ({ page }) => {
    // Navigate to root page
    await page.goto('/');

    // Verify breadcrumbs container is visible
    const breadcrumbs = page.getByRole('navigation', { name: /breadcrumbs/i });
    await expect(breadcrumbs).toBeVisible();

    // Verify home link is present and active
    const homeLink = page.getByRole('link', { name: /home/i });
    await expect(homeLink).toBeVisible();
    await expect(homeLink).toHaveAttribute('href', '/');

    // Verify no other breadcrumb links exist
    const otherLinks = page.getByRole('link').filter({ hasText: /products|electronics|phones/i });
    const linkCount = await otherLinks.count();
    expect(linkCount).toBe(0);

    // Verify current page text is displayed without link
    const currentPageText = page.getByText(/home/i);
    await expect(currentPageText).toBeVisible();
    await expect(currentPageText).not.toHaveAttribute('href');
  });
});
